import type { DocNetAuditResponse, DocNetAuditFilters } from 'src/@types/docnet';
import DocNetBaseService from 'src/services/docnet/DocNetBaseService';
import { api } from 'src/pages/APIs';

export default class DocNetAuditService extends DocNetBaseService {
  public async getAuditLog(
    filters: DocNetAuditFilters = {},
  ): Promise<DocNetAuditResponse> {
    const headers = await this.getHeaders();
    const params = new URLSearchParams();

    if (filters.entity_types?.length) {
      for (const t of filters.entity_types) params.append('entity_types', t);
    } else if (filters.entity_type) {
      params.set('entity_type', filters.entity_type);
    }
    if (filters.entity_ids?.length) {
      for (const id of filters.entity_ids) params.append('entity_ids', id);
    } else if (filters.entity_id) {
      params.set('entity_id', filters.entity_id);
    }
    if (filters.actions?.length) {
      for (const a of filters.actions) params.append('actions', a);
    } else if (filters.action) {
      params.set('action', filters.action);
    }
    if (filters.actor_id) params.set('actor_id', filters.actor_id);
    if (filters.actor_type) params.set('actor_type', filters.actor_type);
    if (filters.actor_name) params.set('actor_name', filters.actor_name);
    if (filters.search) params.set('search', filters.search);
    if (filters.from_date) params.set('from_date', filters.from_date);
    if (filters.to_date) params.set('to_date', filters.to_date);
    if (filters.sort) params.set('sort', filters.sort);
    params.set('skip', String(filters.skip ?? 0));
    params.set('limit', String(filters.limit ?? 50));

    const qs = params.toString();
    const url = `${api.docnet_audit}${qs ? `?${qs}` : ''}`;
    const response = await super.get(url, { headers });
    return response as DocNetAuditResponse;
  }

}
