import { defineStore } from 'pinia';
import DocNetAuditService from 'src/services/docnet/DocNetAuditService';
import type { DocNetActivityEntry, DocNetAuditFilters } from 'src/@types/docnet';

const DEFAULT_PAGE_SIZE = 50;
const auditService = new DocNetAuditService();

export const useDocNetAuditStore = defineStore('docnet_audit', {
  state: () => ({
    items: [] as DocNetActivityEntry[],
    total: 0,
    loading: false,

    // Sticky filters
    search: '',
    entityType: 'all',
    action: 'all',
    actorType: 'all',

    // Sticky pagination
    page: 1,
    pageSize: DEFAULT_PAGE_SIZE,
  }),

  getters: {
    totalPages(state): number {
      return Math.max(1, Math.ceil(state.total / state.pageSize));
    },
    skip(state): number {
      return (state.page - 1) * state.pageSize;
    },
  },

  actions: {
    async fetch() {
      this.loading = true;
      try {
        const filters: DocNetAuditFilters = {
          skip: this.skip,
          limit: this.pageSize,
        };

        if (this.entityType !== 'all') filters.entity_type = this.entityType;
        if (this.action !== 'all') filters.action = this.action;
        if (this.actorType !== 'all') filters.actor_type = this.actorType as 'human' | 'agent' | 'system';
        if (this.search) filters.search = this.search;

        const data = await auditService.getAuditLog(filters);
        this.items = data.items || [];
        this.total = data.total || 0;
      } catch (e) {
        console.error('Failed to fetch audit log:', e);
        this.items = [];
        this.total = 0;
      } finally {
        this.loading = false;
      }
    },

    async setFilter(key: 'entityType' | 'action' | 'actorType', value: string) {
      this[key] = value;
      this.page = 1;
      await this.fetch();
    },

    async setSearch(value: string) {
      this.search = value;
      this.page = 1;
      await this.fetch();
    },

    async goToPage(page: number) {
      this.page = page;
      await this.fetch();
    },

    async setPageSize(size: number) {
      this.pageSize = size;
      this.page = 1;
      await this.fetch();
    },
  },
});
