<template>
  <div class="docnet-activities">
    <!-- Header -->
    <div class="activities-header">
      <div class="activities-title-row">
        <q-icon name="history" size="20px" class="title-icon" />
        <h2 class="activities-title">{{ $t('activities') }}</h2>
        <q-badge v-if="auditStore.total > 0" color="grey">
          {{ auditStore.total }}
        </q-badge>
      </div>
    </div>

    <!-- Filters bar -->
    <div class="filters-bar">
      <q-input
        v-model="searchInput"
        dense
        outlined
        :placeholder="$t('search')"
        class="filter-search"
        clearable
        @update:model-value="onSearchInput"
      >
        <template #prepend>
          <q-icon name="search" size="18px" />
        </template>
      </q-input>

      <q-select
        :model-value="auditStore.entityType"
        :options="entityTypeOptions"
        dense
        borderless
        emit-value
        map-options
        class="filter-select"
        @update:model-value="auditStore.setFilter('entityType', $event)"
      />

      <q-select
        :model-value="auditStore.action"
        :options="actionOptions"
        dense
        borderless
        emit-value
        map-options
        class="filter-select"
        @update:model-value="auditStore.setFilter('action', $event)"
      />

      <q-select
        :model-value="auditStore.actorType"
        :options="actorTypeOptions"
        dense
        borderless
        emit-value
        map-options
        class="filter-select"
        @update:model-value="auditStore.setFilter('actorType', $event)"
      />
    </div>

    <!-- Loading skeleton -->
    <div v-if="auditStore.loading" class="activities-loading">
      <div v-for="n in 8" :key="n" class="skeleton-row">
        <div class="skeleton-badge" />
        <div class="skeleton-content">
          <div class="skeleton-line skeleton-line--title" />
          <div class="skeleton-line skeleton-line--meta" />
        </div>
        <div class="skeleton-time" />
      </div>
    </div>

    <!-- Empty state -->
    <div v-else-if="auditStore.items.length === 0" class="activities-empty">
      <q-icon name="event_note" size="48px" class="empty-icon" />
      <p class="empty-text">{{ $t('no_recent_activity') }}</p>
    </div>

    <!-- Activity table -->
    <div v-else class="activities-table">
      <div
        v-for="entry in auditStore.items"
        :key="entry.id"
        class="activity-row"
        :class="{ 'activity-row--clickable': isNavigable(entry) }"
        @click="goToEntity(entry)"
      >
        <!-- Entity type badge -->
        <q-badge :color="entityColor(entry.entity_type)" class="entity-badge">
          <q-icon :name="entityIcon(entry.entity_type)" size="12px" class="q-mr-xs" />
          {{ formatEntityType(entry.entity_type) }}
        </q-badge>

        <!-- Action badge -->
        <q-badge :color="actionColor(entry.action)" class="action-badge">
          <q-icon :name="actionIcon(entry.action)" size="12px" class="q-mr-xs" />
          {{ formatAction(entry.action) }}
        </q-badge>

        <!-- Main content — summary + inline changes -->
        <div class="activity-body">
          <span v-if="resolveActorName(entry)" class="actor-name">{{ resolveActorName(entry) }}</span>
          <span v-if="entry.summary" class="summary-text">{{ resolveActorName(entry) ? ' — ' : '' }}{{ truncate(entry.summary, 120) }}</span>
          <span v-if="inlineChange(entry)" class="change-text"> ({{ inlineChange(entry) }})</span>
        </div>

        <!-- Time -->
        <div class="activity-time">{{ formatActivityTime(entry.created_on) }}</div>
      </div>
    </div>

    <!-- Pagination -->
    <div v-if="auditStore.total > 0" class="activities-pagination">
      <div class="row items-center">
        <PaginationSettings
          label="records_per_page"
          settings-key="AUDIT_PAGINATION_SIZE"
          :options="['10', '20', '25', '50']"
          :model-value="String(auditStore.pageSize)"
          @update:model-value="onPageSizeChange"
        />
        <q-separator vertical class="q-mx-md" />
        <q-pagination
          :model-value="auditStore.page"
          color="primary"
          :max="auditStore.totalPages"
          :max-pages="6"
          input
          boundary-links
          gutter="none"
          class="docbits-pagination"
          @update:model-value="auditStore.goToPage($event)"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { useDocNetAuditStore } from 'src/store/DocNet/docnet-audit.store';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';
import PaginationSettings, { getSavedPaginationSize } from 'src/components/Table/PaginationSettings.vue';
import dateMixin from 'src/utils/date';
import type { DocNetActivityEntry } from 'src/@types/docnet';
import {
  actionColor as sharedActionColor,
  actionIcon as sharedActionIcon,
  entityColor as sharedEntityColor,
  entityIcon as sharedEntityIcon,
  formatAction as sharedFormatAction,
  formatEntityType as sharedFormatEntityType,
  inlineChange as sharedInlineChange,
  truncate as sharedTruncate,
} from 'src/utils/docnet/auditFormatting';

let searchTimeout: ReturnType<typeof setTimeout> | null = null;

export default defineComponent({
  name: 'DocNetActivities',

  components: {
    PaginationSettings,
  },

  mixins: [dateMixin],

  setup() {
    const dropdownStore = useDropdownStore();
    const { usersMap } = storeToRefs(dropdownStore);
    const { prepareUsersDropdown } = dropdownStore;

    return {
      usersMap,
      prepareUsersDropdown,
    };
  },

  data() {
    return {
      searchInput: '',
    };
  },

  computed: {
    auditStore() {
      return useDocNetAuditStore();
    },
    entityTypeOptions(): { label: string; value: string }[] {
      return [
        { label: this.$t('all_entities'), value: 'all' },
        { label: this.$t('issues'), value: 'issue' },
        { label: this.$t('subtasks'), value: 'subtask' },
        { label: this.$t('missions'), value: 'mission' },
        { label: this.$t('projects'), value: 'project' },
        { label: this.$t('agents'), value: 'agent' },
        { label: this.$t('agent_runs'), value: 'agent_run' },
        { label: this.$t('emails'), value: 'email' },
        { label: this.$t('labels'), value: 'label' },
        { label: this.$t('approvals'), value: 'approval' },
        { label: this.$t('attachments'), value: 'attachment' },
        { label: this.$t('inbox'), value: 'inbox_item' },
      ];
    },
    actionOptions(): { label: string; value: string }[] {
      return [
        { label: this.$t('all_actions'), value: 'all' },
        { label: this.$t('created'), value: 'created' },
        { label: this.$t('updated'), value: 'updated' },
        { label: this.$t('deleted'), value: 'deleted' },
        { label: this.$t('toggled'), value: 'toggled' },
        { label: this.$t('marked_read'), value: 'marked_read' },
        { label: this.$t('marked_unread'), value: 'marked_unread' },
        { label: this.$t('ingested'), value: 'ingested' },
        { label: this.$t('classification_changed'), value: 'classification_changed' },
        { label: this.$t('project_assigned'), value: 'project_assigned' },
        { label: this.$t('config_rollback'), value: 'config_rollback' },
        { label: this.$t('approved'), value: 'approved' },
        { label: this.$t('rejected'), value: 'rejected' },
        { label: this.$t('run_created'), value: 'run_created' },
        { label: this.$t('run_completed'), value: 'run_completed' },
        { label: this.$t('run_failed'), value: 'run_failed' },
        { label: this.$t('run_stopped'), value: 'run_stopped' },
        { label: this.$t('succeeded'), value: 'succeeded' },
        { label: this.$t('acted:approve'), value: 'acted:approve' },
        { label: this.$t('acted:reject'), value: 'acted:reject' },
        { label: this.$t('acted:comment'), value: 'acted:comment' },
      ];
    },
    actorTypeOptions(): { label: string; value: string }[] {
      return [
        { label: this.$t('all_actors'), value: 'all' },
        { label: this.$t('actor_human'), value: 'human' },
        { label: this.$t('actor_agent'), value: 'agent' },
        { label: this.$t('actor_system'), value: 'system' },
      ];
    },
  },

  async mounted() {
    this.searchInput = this.auditStore.search;
    const savedSize = await getSavedPaginationSize('AUDIT_PAGINATION_SIZE');
    this.prepareUsersDropdown();
    if (savedSize !== this.auditStore.pageSize) {
      await this.auditStore.setPageSize(savedSize);
    } else {
      await this.auditStore.fetch();
    }
  },

  methods: {
    /** Resolve actor name: humans use usersMap via actor_id, agents/system use actor_name */
    resolveActorName(entry: DocNetActivityEntry): string {
      if (entry.actor_type === 'human' && entry.actor_id) {
        const user = this.usersMap.get(Number(entry.actor_id));
        if (user) {
          return `${user.first_name} ${user.last_name}`.trim();
        }
        return '';
      }
      return entry.actor_name || '';
    },

    onPageSizeChange(newSize: string) {
      this.auditStore.setPageSize(Number(newSize));
    },

    onSearchInput(value: string | null) {
      if (searchTimeout) clearTimeout(searchTimeout);
      searchTimeout = setTimeout(() => {
        this.auditStore.setSearch(value || '');
      }, 300);
    },

    // The visual mappers + delta formatter live in
    // ``src/utils/docnet/auditFormatting.ts`` so the per-mission
    // timeline can reuse the same icon/color/action vocabulary.
    // These methods are thin delegations that bind ``$t`` for i18n.
    formatEntityType(type: string | undefined): string {
      return sharedFormatEntityType(type, (k) => this.$t(k));
    },

    entityIcon(type: string | undefined): string {
      return sharedEntityIcon(type);
    },

    entityColor(type: string | undefined): string {
      return sharedEntityColor(type);
    },

    formatAction(action: string): string {
      return sharedFormatAction(action, (k) => this.$t(k));
    },

    actionColor(action: string): string {
      return sharedActionColor(action);
    },

    actionIcon(action: string): string {
      return sharedActionIcon(action);
    },

    inlineChange(entry: DocNetActivityEntry): string {
      return sharedInlineChange(entry.old_values, entry.new_values);
    },

    /** Navigate to the entity — agent_run links to its parent issue */
    isNavigable(entry: DocNetActivityEntry): boolean {
      if (entry.entity_type === 'agent_run') {
        return !!(entry.new_values?.issue_id || entry.old_values?.issue_id);
      }
      const navigable = ['issue', 'subtask', 'mission', 'project', 'email', 'inbox_item'];
      return navigable.includes(entry.entity_type || '');
    },

    truncate(text: string, maxLen: number): string {
      return sharedTruncate(text, maxLen);
    },

    /** Show relative time for recent, then user's preferred date format for older */
    formatActivityTime(dateStr: string): string {
      if (!dateStr) return '';
      const date = new Date(dateStr);
      if (isNaN(date.getTime())) return '';
      const diff = Date.now() - date.getTime();
      const mins = Math.floor(diff / 60000);
      if (mins < 1) return this.$t('just_now');
      if (mins < 60) return this.$t('minutes_ago', { n: mins });
      const hours = Math.floor(mins / 60);
      if (hours < 24) return this.$t('hours_ago', { n: hours });
      // Older than 24h: use user's date format preference
      return this.formatDateAccordingToPreference(dateStr);
    },

    goToEntity(entry: DocNetActivityEntry) {
      if (!this.isNavigable(entry)) return;
      // Agent runs link to their parent issue
      if (entry.entity_type === 'agent_run') {
        const issueId = (entry.new_values?.issue_id || entry.old_values?.issue_id) as string;
        if (issueId) {
          this.$router.push(`/doc-net/issues/${issueId}`);
        }
        return;
      }
      const routes: Record<string, string> = {
        issue: '/doc-net/issues/',
        subtask: '/doc-net/issues/',
        mission: '/doc-net/missions/',
        project: '/doc-net/projects/',
        email: '/doc-net/email/',
        inbox_item: '/doc-net/inbox/',
      };
      const base = routes[entry.entity_type || ''];
      if (base && entry.entity_id) {
        this.$router.push(base + entry.entity_id);
      }
    },
  },
});
</script>

